import shutil

from pyspark.sql import functions as F


class CarrierFeed:
    # Stands in for the carrier's server. Don't change this.
    # It is still starting up: the first 4 calls of a run time out, and every call after that answers.
    def __init__(self, events):
        self.events = events
        self.calls = 0

    def fetch(self, day):
        self.calls += 1
        if self.calls <= 4:
            raise TimeoutError("the carrier feed did not answer")
        return self.events.filter(F.col("load_date") == day)


def load(batch, path):
    # Appends one day's events to the tracking table and returns how many it loaded. Don't change this.
    # Event numbers are stored as integers, so an id that can't be read fails the write.
    digits = F.substring("event_id", 2, 20)
    batch.select("event_id", "shipment_id", "load_date", digits.cast("int").alias("event_no")).write.mode("append").parquet(path)
    return batch.count()


def load_day(feed, day, path):
    # Loads one day and returns its log row: (load_date, status, attempts, rows, error).
    rows = load(feed.fetch(day), path)
    return (day, "loaded", 1, rows, None)


def solve(shipment_events):
    path = "/tmp/tracking/events"
    shutil.rmtree(path, ignore_errors=True)  # start from an empty table on every run
    feed = CarrierFeed(shipment_events)
    days = sorted(row["load_date"] for row in shipment_events.select("load_date").distinct().collect())
    log = [load_day(feed, day, path) for day in days]
    return spark.createDataFrame(log, "load_date DATE, status STRING, attempts INT, rows BIGINT, error STRING")
